"lpSearch": "மொழிகளைத் தேடுங்கள்",
"shTitle": "AI ஷேக்",
"shSub": "கற்றுக்கொள்ள உதவும் அன்பான ஆசிரியர்",
"shNote": "AI ஷேக் ஒரு செயற்கை நுண்ணறிவு; உண்மையான அறிஞர் அல்ல, தவறுகள் செய்யக்கூடும். முக்கியமான மார்க்கத் தீர்ப்புகளுக்கு தகுதிவாய்ந்த அறிஞர் அல்லது இமாமிடம் கேளுங்கள்.",
"shPlaceholder": "கேள்வியைக் கேளுங்கள்…",
"shSend": "அனுப்பு",
"shSignIn": "AI ஷேக்கிடம் பேச உள்நுழையுங்கள்",
"shOff": "AI ஷேக் இன்னும் செயல்படுத்தப்படவில்லை.",
"shErr": "ஷேக்கால் இப்போது பதிலளிக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
"shLimit": "இன்றைய கேள்வி வரம்பை எட்டிவிட்டீர்கள். நாளை மீண்டும் வாருங்கள்.",
"shHello": "அஸ்ஸலாமு அலைக்கும்! நான் உங்கள் AI ஷேக். எந்த ஸூரா அல்லது ஆயத்தைப் பற்றியும், சொற்களின் பொருளைப் பற்றியும், கற்றலை எப்படித் தொடங்குவது என்றும் கேளுங்கள் — படிப்படியாக எளிதாக விளக்குகிறேன்.",
"shQ1": "இந்த ஸூராவை எளிமையாக விளக்குங்கள்",
"shQ2": "அல்-ஃபாத்திஹாவின் பொருளைக் கற்றுத்தாருங்கள்",
"shQ3": "தஜ்வீத் கற்க எப்படித் தொடங்கலாம்?",
"shQ4": "இன்றைக்கு ஒரு சிறிய பாடம் சொல்லுங்கள்",
"shAsk": "ஷேக்கிடம் கேளுங்கள்",
