"shNew": "புதிய உரையாடல்",
"shThinking": "ஷேக் யோசிக்கிறார்…",
"emSubject": "Tilawa-வில் இணைந்ததற்கு நன்றி",
"emTitle": "இணைந்ததற்கு நன்றி",
"emGreeting": "அஸ்ஸலாமு அலைக்கும் {name},",
"emBody": "உங்கள் Tilawa கணக்கை உருவாக்கியதற்கு நன்றி. குர்ஆன் உங்கள் இதயத்தின் ஒளியாக இருக்க அல்லாஹ் அருள்புரிவானாக. இப்போது உங்கள் மொழியில் வாசிக்கலாம், நூற்றுக்கணக்கான குர்ஆன் ஓதுபவர்களைக் கேட்கலாம், மேலும் உங்கள் சாதனங்கள் அனைத்திலும் சேமித்த இடங்களைப் பயன்படுத்தலாம்.",
"emCta": "Tilawa-வைத் திறக்கவும்",
